import numpy as np

from mcf.research.arena.indicators import compute

SIDE = 'long'
GEOM = 'hold'
WINDOW = (950, 1100)          # bar close lo <= tod <= hi (inclusive, as the YAML window)
MIN_ADV = 50000000.0
CONTEXT = ['breadth']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('atr_d_pct', '>=', 4.4),
    ('breadth', '>', 0.7),
    ('lower_wick', '>=', 0.33),
    ('rsiSlope', '>=', 19.0),
]
LAYERS = ['atr_d_pct >= 4.4', 'breadth > 0.7', 'lower_wick >= 0.33', 'rsiSlope >= 19', 'window 950-1100']


def mask(df) -> np.ndarray:
    x = compute(df, names=['atr_d_pct', 'lower_wick', 'rsiSlope'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
